//! Reference ports of Dragon Warrior (NES) mechanics, from the formula reference page.
//! `zig build romcheck` runs each one against the original ROM routine in a 6502 interpreter.
//! Copy what you need into the engine; keep these as the known-good baseline.
//!
//! Generated by docs/reference/build.mjs from docs/reference/template.html. Edit the page, not this file.

/// Call once per 1/60 s while the game is waiting for player input.
/// The original's joypad read ($C608) calls $C55B, and the input loops poll once per frame.
pub fn idleFrames(rng: *Rng, frames: u32) void {
    var i: u32 = 0;
    while (i < frames) : (i += 1) _ = rng.next();
}

/// NTSC NES: 60.0988 frames/s.
pub fn framesFromNs(ns: u64) u32 {
    return @intCast(@min(ns / 16_639_267, std.math.maxInt(u32)));
}

const std = @import("std");

pub const Rng = struct {
    /// $94 (low byte) and $95 (high byte) as one u16.
    state: u16,
    /// Carry left by the final ADC #$00. $EEBB adds it by accident.
    carry: u1 = 0,

    pub fn init(seed: u16) Rng {
        return .{ .state = seed };
    }

    /// $C55B. Returns $95 (RAND).
    pub fn next(self: *Rng) u8 {
        const sum = @addWithOverflow(self.state *% 0x303, 0x81);
        self.state = sum[0];
        self.carry = sum[1];
        return self.hi();
    }

    /// Re-read $95 without advancing (many routines do this).
    pub fn hi(self: Rng) u8 {
        return @truncate(self.state >> 8);
    }

    pub fn lo(self: Rng) u8 {
        return @truncate(self.state);
    }

    /// $E675 writes a masked value back into $95. See "Dodge".
    pub fn setHi(self: *Rng, value: u8) void {
        self.state = (@as(u16, value) << 8) | self.lo();
    }
};

test "Rng matches project sequence" {
    var rng: Rng = .init(1);
    try std.testing.expectEqual(3, rng.next());
    try std.testing.expectEqual(151, rng.next());
}

fn next6502(lo: *u8, hi: *u8) void {
    const old_lo = lo.*;
    const old_hi = hi.*;
    const c1: u1 = @truncate(lo.* >> 7); // ASL $94
    lo.* <<= 1;
    hi.* = (hi.* << 1) | c1; // ROL $95
    const a = @addWithOverflow(old_lo, lo.*); // CLC, ADC
    lo.* = a[0];
    hi.* = hi.* +% old_hi +% a[1]; // ADC $3D
    hi.* = lo.* +% hi.*; // CLC, ADC $95
    const b = @addWithOverflow(lo.*, 0x81); // CLC, ADC #$81
    lo.* = b[0];
    hi.* +%= b[1]; // ADC #$00
}

test "Rng.next is exact for all 65536 states" {
    var s: u32 = 0;
    while (s < 0x10000) : (s += 1) {
        var rng: Rng = .init(@intCast(s));
        _ = rng.next();
        var lo: u8 = @truncate(s);
        var hi: u8 = @truncate(s >> 8);
        next6502(&lo, &hi);
        try std.testing.expectEqual(lo, rng.lo());
        try std.testing.expectEqual(hi, rng.hi());
    }
}

/// u8 × u8 then take $41 (the high byte). Used for every "scale by RAND" formula.
pub fn mulHi(a: u8, b: u8) u8 {
    return @truncate((@as(u16, a) * b) >> 8);
}

pub const HealKind = enum { herb, heal, healmore };

pub fn healAmount(rng: *Rng, kind: HealKind) u8 {
    const r = rng.next();
    return switch (kind) {
        .herb => (r & 0x07) + 0x17, // $DD03: AND #$07 (guide table is wrong)
        .heal => (r & 0x07) + 0x0A,
        .healmore => (r & 0x0F) + 0x55,
    };
}

/// HEAL/HEALMORE: ADC $C5 / BCS / CMP $CA / BCC, with no overflow panic.
pub fn applyHeal(hp: u8, max_hp: u8, amount: u8) u8 {
    const sum = @addWithOverflow(hp, amount);
    return if (sum[1] == 1 or sum[0] >= max_hp) max_hp else sum[0];
}

/// Herb ($DD08) has no BCS, so the add wraps. Unreachable with real max HP.
pub fn applyHerb(hp: u8, max_hp: u8, amount: u8) u8 {
    const sum = hp +% amount;
    return if (sum >= max_hp) max_hp else sum;
}

test applyHeal {
    try std.testing.expectEqual(20, applyHeal(15, 20, 10));
    try std.testing.expectEqual(250, applyHeal(200, 250, 100)); // would overflow u8
}

pub const Light = struct {
    radius: u8 = 1, // $D0
    timer: u8 = 0, // $DA

    pub fn castRadiant(self: *Light) void {
        self.* = .{ .radius = 7, .timer = 0x50 };
    }

    /// Torch leaves the timer at 0, which is why it never fades.
    pub fn useTorch(self: *Light) void {
        self.* = .{ .radius = 3 };
    }

    /// $CA56.
    pub fn step(self: *Light) void {
        if (self.timer == 0) return; // LDA $DA / BEQ
        self.timer -= 1;
        if (self.timer != 0 or self.radius == 1) return;
        self.timer = 0x3C;
        self.radius -= 2;
    }

    pub fn tiles(self: Light) u8 {
        return (self.radius - 1) / 2;
    }
};

test "Radiant lasts 200 steps" {
    var light: Light = .{};
    light.castRadiant();
    var steps: u32 = 0;
    while (light.tiles() > 0) : (steps += 1) light.step();
    try std.testing.expectEqual(200, steps);
}

pub fn repelled(hero_defense: u8, enemy_strength: u8) bool {
    const half = hero_defense >> 1;
    if (enemy_strength < half) return true;
    return (enemy_strength >> 1) >= enemy_strength - half;
}

pub const Repel = struct {
    counter: u8 = 0, // $DB

    pub fn castRepel(self: *Repel) void {
        self.counter = 0xFF;
    }

    pub fn useFairyWater(self: *Repel) void {
        self.counter = 0xFE;
    }

    pub const Expired = enum { repel, fairy_water };

    /// $CA6C. Both last 127 steps: 0xFF ends on 1, 0xFE ends on 0.
    pub fn step(self: *Repel) ?Expired {
        if (self.counter == 0) return null;
        self.counter -%= 2;
        if (self.counter > 1) return null;
        defer self.counter = 0;
        return if (self.counter == 1) .repel else .fairy_water;
    }

    pub fn active(self: Repel) bool {
        return self.counter != 0;
    }
};

test repelled {
    try std.testing.expect(repelled(51, 50)); // guide's prose says otherwise
    try std.testing.expect(!repelled(48, 50));
}

test "REPEL and Fairy Water both last 127 steps" {
    for ([_]u8{ 0xFF, 0xFE }) |start| {
        var r: Repel = .{ .counter = start };
        var steps: u32 = 1;
        while (r.step() == null) steps += 1;
        try std.testing.expectEqual(127, steps);
    }
}

pub fn silverHarp(rng: *Rng) EnemyId {
    while (true) {
        const r = rng.next() & 0x07;
        if (r != 5 and r != 7) return @fromBackingInt(r);
    }
}

/// Tile values from the map lookup (bank 0 $AC17), kept in $E0 while you walk.
/// tileAt (in "Map data and the tile lookup") says where each comes from.
pub const Tile = enum(u8) {
    grass = 0x00,
    desert = 0x01,
    hills = 0x02,
    stairs_up = 0x03,
    brick = 0x04,
    stairs_down = 0x05,
    swamp = 0x06,
    town = 0x07,
    cave = 0x08,
    castle = 0x09,
    bridge = 0x0A,
    forest = 0x0B,
    chest = 0x0C,
    barrier = 0x0D,
    /// Shop counters. TALK reaches across one ($CFF9).
    counter = 0x0E,
    water = 0x0F,
    wall = 0x10,
    door = 0x11,
    mountain = 0x12,
    shop_sign = 0x13,
    inn_sign = 0x14,
    /// The throne room's border.
    empty = 0x15,
    blank = 0x16,
    princess = 0x17,
    /// 0x18-0x26: overworld water with land on some side (shore). See isWater.
    _,
};

pub fn encounterMask(tile: Tile, x: u8, y: u8) u8 {
    return switch (tile) {
        .desert, .hills => 0x07,
        .swamp, .forest, .brick, .barrier => 0x0F,
        else => if ((x ^ y) & 1 == 0) 0x1F else 0x0F,
    };
}

/// $F522: 8x8 zone grid, two 4-bit zones per byte.
pub const zone_table = [32]u8{
    0x33, 0x22, 0x35, 0x45,
    0x32, 0x12, 0x33, 0x45,
    0x41, 0x00, 0x23, 0x45,
    0x51, 0x1C, 0x66, 0x66,
    0x55, 0x4C, 0x97, 0x77,
    0xA9, 0x8C, 0xCC, 0x87,
    0xAA, 0xBC, 0xDD, 0x98,
    0xBB, 0xCD, 0xDC, 0x99,
};

pub fn overworldZone(x: u8, y: u8) u8 {
    const gx = x / 15;
    const gy = y / 15;
    const byte = zone_table[@as(usize, gy) * 4 + (gx >> 1)];
    return if (gx & 1 == 1) byte & 0x0F else byte >> 4;
}

test overworldZone {
    try std.testing.expectEqual(0, overworldZone(0x2B, 0x2C)); // south of Tantegel
    try std.testing.expectEqual(3, overworldZone(0, 0)); // Garinham corner
}

/// $F542: zones for maps 0x0F-0x1B.
pub const dungeon_zones = [13]u8{ 0x10, 0x11, 0x11, 0x11, 0x12, 0x12, 0x13, 0x13, 0x0E, 0x0E, 0x07, 0x0F, 0x0F };

/// $CED8: zone for a non-overworld map ($45), or null for no random encounters.
/// `map_flag` is $16, the map type (mapKind): 0x20 for every map from 0x0F up.
pub fn mapZone(map: u8, map_flag: u8) ?u8 {
    return switch (map) {
        0x02 => 0x10,
        0x03 => 0x0D,
        0x06 => 0x12,
        0x0F...0x1B => if (map_flag == 0x20) dungeon_zones[map - 0x0F] else null,
        else => null,
    };
}

pub fn pickEnemy(rng: *Rng, zone: u8) EnemyId {
    while (true) {
        const slot = rng.next() & 0x07;
        if (slot < 5) return enemy_sets[zone][slot];
    }
}

pub const StepContext = struct {
    /// $45: 1 = overworld.
    map: u8,
    /// $16, the map type (mapKind). The dungeon branch checks it for 0x20.
    map_flag: u8 = 0x20,
    tile: Tile,
    x: u8,
    y: u8,
    hero_defense: u8,
    repel_active: bool,
};

/// The step's roll ($CDA2) and the encounter after it. takeStep() below does
/// the whole step, including the swamp/barrier damage that sits in between.
pub fn stepEncounter(rng: *Rng, ctx: StepContext) ?EnemyId {
    _ = rng.next();
    return encounterAfterRoll(rng, ctx);
}

/// $CDFB on: the tile mask tests the roll already in $95.
pub fn encounterAfterRoll(rng: *Rng, ctx: StepContext) ?EnemyId {
    if (rng.hi() & encounterMask(ctx.tile, ctx.x, ctx.y) != 0) return null;

    const overworld = ctx.map == 0x01;
    const zone: u8 = if (overworld)
        overworldZone(ctx.x, ctx.y)
    else
        mapZone(ctx.map, ctx.map_flag) orelse return null;
    if (overworld and zone == 0) {
        const mask: u8 = if (ctx.tile == .hills) 0x03 else 0x01;
        if (rng.next() & mask != 0) return null;
    }

    const id = pickEnemy(rng, zone);
    if (overworld and ctx.repel_active and
        repelled(ctx.hero_defense, enemies[@backingInt(id)].str)) return null;
    return id;
}

test "steps near Tantegel eventually meet slimes" {
    var rng: Rng = .init(0);
    var found: ?EnemyId = null;
    while (found == null) found = stepEncounter(&rng, .{
        .map = 0x01,
        .tile = @fromBackingInt(0x00),
        .x = 0x2B,
        .y = 0x2C,
        .hero_defense = 2,
        .repel_active = false,
    });
    try std.testing.expect(found.? == .slime or found.? == .red_slime);
}

/// Armor index (($BE >> 2) & 7) of the two regenerating armors.
pub const magic_armor = 6;
pub const erdricks_armor = 7;

/// $CCF6, first thing on every step, on every map. Erdrick's Armor: +1 HP.
/// Magic Armor: +1 HP every 4th step, counted by $E3, which ticks only while
/// Magic Armor is worn and is never reset.
pub fn armorRegen(hp: *u8, max_hp: u8, armor: u3, counter: *u8) void {
    switch (armor) {
        erdricks_armor => {},
        magic_armor => {
            counter.* +%= 1;
            if (counter.* & 0x03 != 0) return;
        },
        else => return,
    }
    hp.* +%= 1; // INC $C5
    if (hp.* >= max_hp) hp.* = max_hp;
}

/// $CDC6 (swamp, -2) and $CE17 (barrier, -15), after the step's RNG call.
/// Erdrick's Armor is immune. HP stops at 0. Returns true if the hero died
/// ($EDA7); there's no encounter check then.
pub fn terrainDamage(hp: *u8, tile: Tile, armor: u3) bool {
    const damage: u8 = switch (tile) {
        .swamp => 2,
        .barrier => 15,
        else => return false,
    };
    if (armor == erdricks_armor) return false;
    hp.* -|= damage;
    return hp.* == 0;
}

/// $E4 story bits the step code reads.
pub const Story = struct {
    pub const golem_beaten: u8 = 0x02;
    pub const dragonlord_beaten: u8 = 0x04;
    pub const green_dragon_beaten: u8 = 0x40;
};

/// $CD51-$CD9F: fixed battles, before the step's RNG call.
/// The Axe Knight has no flag, so he's there every time you step on the tile.
pub fn fixedBattle(map: u8, x: u8, y: u8, story: u8) ?EnemyId {
    if (map == 0x03 and x == 0x12 and y == 0x0C) return .axe_knight;
    if (map == 0x15 and x == 0x04 and y == 0x0E and story & Story.green_dragon_beaten == 0) return .green_dragon;
    if (map == 0x01 and x == 0x49 and y == 0x64 and story & Story.golem_beaten == 0) return .golem;
    return null;
}

/// $CDB6: tiles 0x07-0x09 are entrances; the step continues at $D941 (map change).
pub fn isEntrance(tile: Tile) bool {
    const t = @backingInt(tile);
    return t >= 0x07 and t < 0x0A;
}

pub const StepHero = struct {
    hp: u8, // $C5
    max_hp: u8, // $CA
    armor: u3, // ($BE >> 2) & 7
    magic_armor_steps: u8 = 0, // $E3
    cf: u8 = 0, // curse bits (see Worn)
};

pub const StepEvent = union(enum) {
    none,
    /// Dragonlord beaten and standing at Tantegel (10 or 11, 8).
    ending,
    /// Cursed on Tantegel's row 27: sent out through the castle's exit ($B228).
    kicked_out,
    fixed_battle: EnemyId,
    /// Tiles 0x07-0x09 continue at $D941 (the map change), after the RNG call.
    entrance,
    died,
    battle: EnemyId,
};

/// $CBF7: everything after a move that stays inside the map. Light and REPEL
/// timers tick separately, in the main loop ($CA56) after this returns.
pub fn takeStep(rng: *Rng, hero: *StepHero, ctx: StepContext, story: u8) StepEvent {
    if (story & Story.dragonlord_beaten != 0) {
        if (ctx.map == 0x04 and ctx.y == 0x08 and (ctx.x == 0x0A or ctx.x == 0x0B)) return .ending;
    } else {
        armorRegen(&hero.hp, hero.max_hp, hero.armor, &hero.magic_armor_steps);
        if (ctx.map == 0x04 and cursed(hero.cf) and ctx.y == 0x1B) return .kicked_out;
        if (fixedBattle(ctx.map, ctx.x, ctx.y, story)) |id| return .{ .fixed_battle = id };
    }
    _ = rng.next(); // $CDA2: every step, even onto an entrance
    if (isEntrance(ctx.tile)) return .entrance;
    if (story & Story.dragonlord_beaten != 0) return .none; // $CDBF: no encounters
    if (terrainDamage(&hero.hp, ctx.tile, hero.armor)) return .died;
    return if (encounterAfterRoll(rng, ctx)) |id| .{ .battle = id } else .none;
}

test "Magic Armor heals every 4th step" {
    var hp: u8 = 10;
    var counter: u8 = 0;
    for (0..8) |_| armorRegen(&hp, 50, magic_armor, &counter);
    try std.testing.expectEqual(12, hp);
}

test "a barrier step that kills skips the encounter check" {
    var rng: Rng = .init(0);
    var hero: StepHero = .{ .hp = 15, .max_hp = 30, .armor = 0 };
    const ev = takeStep(&rng, &hero, .{ .map = 0x01, .tile = .barrier, .x = 10, .y = 10, .hero_defense = 0, .repel_active = false }, 0);
    try std.testing.expectEqual(StepEvent.died, ev);
    try std.testing.expectEqual(0x0081, rng.state); // only the step's own call
}

