pub fn rollEnemyHp(rng: *Rng, id: EnemyId) u8 {
    const max = enemies[@backingInt(id)].hp;
    if (id == .dragonlord2) return max;
    return max - (mulHi(rng.next(), max) >> 2);
}

pub fn rollGold(rng: *Rng, id: EnemyId) u8 {
    const gp = enemies[@backingInt(id)].gp;
    return mulHi(gp, (rng.next() & 0x3F) + 0xC0);
}

pub const ResistKind = enum { sleep, stopspell, hurt };

pub fn spellLands(rng: *Rng, id: EnemyId, kind: ResistKind) bool {
    const e = enemies[@backingInt(id)];
    const resist: u8 = switch (kind) {
        .sleep => e.sr >> 4,
        .stopspell => e.sr & 0x0F,
        .hurt => e.dr >> 4,
    };
    return (rng.next() & 0x0F) >= resist;
}

pub fn enemyDodges(rng: *Rng, id: EnemyId) bool {
    const r = rng.next() & 0x3F;
    rng.setHi(r); // STA $95
    const chance = enemies[@backingInt(id)].dr & 0x0F;
    if (chance == 0) return false;
    return r <= chance - 1;
}

pub const Action = enum { attack, sleep, stopspell, heal, healmore, hurt, hurtmore, fire, strong_fire };

pub const HeroStatus = struct {
    asleep: bool = false, // $DF bit 7
    spell_stopped: bool = false, // $DF bit 4
};

pub fn chooseAction(rng: *Rng, id: EnemyId, hp: u8, hero: HeroStatus) Action {
    const e = enemies[@backingInt(id)];
    const p = e.pattern;
    if ((rng.next() & 0x30) < (p & 0x30)) {
        const low_hp = hp <= e.hp >> 2; // table HP, not rolled
        switch (p >> 6) {
            0 => if (!hero.asleep) return .sleep,
            1 => if (!hero.spell_stopped) return .stopspell,
            2 => if (low_hp) return .heal,
            3 => if (low_hp) return .healmore,
            else => unreachable,
        }
    }
    if ((rng.next() & 0x03) < (p & 0x03)) {
        return switch ((p >> 2) & 0x03) {
            0 => .hurt,
            1 => .hurtmore,
            2 => .fire,
            3 => .strong_fire,
            else => unreachable,
        };
    }
    return .attack;
}

test "Starwyvern at low HP" {
    var counts: [9]u32 = @splat(0);
    var s: u32 = 0;
    while (s < 0x10000) : (s += 1) {
        var rng: Rng = .init(@intCast(s));
        counts[@backingInt(chooseAction(&rng, .starwyvern, 10, .{}))] += 1;
    }
    try std.testing.expectEqual(49152, counts[@backingInt(Action.healmore)]); // 3/4
    try std.testing.expectEqual(4096, counts[@backingInt(Action.fire)]); // 1/16
}

/// $F030, shared by hero and enemy. The ROR makes the add effectively 9-bit.
pub fn variableDamage(rng: *Rng, d: u8) u8 {
    const r = rng.next();
    const sum = @as(u16, mulHi(r, d +% 1)) + d;
    return @truncate(sum >> 2);
}

pub fn enemyAttack(rng: *Rng, enemy_str: u8, hero_def: u8) u8 {
    const half = hero_def >> 1;
    const t = (enemy_str >> 1) + 1;
    if (enemy_str >= half and enemy_str - half >= t)
        return variableDamage(rng, enemy_str - half);
    return (mulHi(rng.next(), t) + 2) / 3;
}

pub const Armor = enum { other, magic, erdricks };

pub fn reduce(dmg: u8) u8 {
    return (dmg / 3) * 2;
}

/// Damage to the hero (or HP restored to the enemy for heals).
pub fn enemyEffect(rng: *Rng, action: Action, armor: Armor) u8 {
    const r = rng.next();
    return switch (action) {
        .hurt => if (armor != .other) reduce((r & 0x07) + 0x03) else (r & 0x07) + 0x03,
        .hurtmore => if (armor != .other) reduce((r & 0x0F) + 0x1E) else (r & 0x0F) + 0x1E,
        .fire => if (armor == .erdricks) reduce((r & 0x07) + 0x10) else (r & 0x07) + 0x10,
        .strong_fire => if (armor == .erdricks) reduce((r & 0x07) + 0x41) else (r & 0x07) + 0x41,
        .heal => (r & 0x07) + 0x14,
        .healmore => (r & 0x0F) + 0x55,
        .attack, .sleep, .stopspell => unreachable, // handled elsewhere
    };
}

/// $ECB7: CLC / ADC $E2 / CMP $0102. Caps at the TABLE max, which can be
/// above the HP this enemy rolled at the start of the fight.
pub fn enemyHealed(hp: u8, id: EnemyId, amount: u8) u8 {
    const max = enemies[@backingInt(id)].hp;
    const sum = hp +% amount;
    return if (sum >= max) max else sum;
}

/// $EBEE: every enemy spell first checks whether the hero stopped its spells.
/// A blocked cast ends the enemy's turn with no RNG call. Fire isn't a spell.
pub fn enemySpellBlocked(action: Action, enemy_stopped: bool) bool {
    return enemy_stopped and switch (action) {
        .sleep, .stopspell, .heal, .healmore, .hurt, .hurtmore => true,
        .attack, .fire, .strong_fire => false,
    };
}

/// $E5D6, at the start of the hero's turn. Waking means you act this turn.
pub fn heroWakes(rng: *Rng) bool {
    return rng.next() & 1 == 1; // LSR, BCS -> wake
}

/// $EB21, at the start of a sleeping enemy's turn: reroll 0, wake on 1.
/// 1/3 per turn. The turn SLEEP lands skips this roll ($E787 -> $EB3E).
pub fn enemyWakes(rng: *Rng) bool {
    while (true) {
        const r = rng.next() & 0x03;
        if (r != 0) return r == 1;
    }
}

test "sleep never survives 6 failed wake rolls at 4 calls/turn" {
    var s: u32 = 0;
    while (s < 0x10000) : (s += 1) {
        var rng: Rng = .init(@intCast(s));
        var rolls: u32 = 0;
        while (true) {
            for (0..3) |_| _ = rng.next(); // special 1, special 2, damage
            rolls += 1;
            if (heroWakes(&rng)) break;
        }
        try std.testing.expect(rolls <= 6);
    }
}

pub fn stopspellLands(rng: *Rng, armor: Armor) bool {
    if (armor == .erdricks) return false; // no RNG call
    return rng.next() & 1 == 1;
}

/// $E634: ignores enemy agility.
pub fn excellentDamage(rng: *Rng, attack: u8) u8 {
    return attack - mulHi(rng.next(), attack >> 1);
}

/// $EFE5: regular or minimal (0/1) damage.
pub fn heroDamage(rng: *Rng, attack: u8, enemy_agi: u8) u8 {
    const half = enemy_agi >> 1;
    if (attack < half or attack - half < 2) return rng.next() & 0x01;
    return variableDamage(rng, attack - half);
}

pub const FightResult = struct { damage: u8, excellent: bool = false, dodged: bool = false };

/// $E60C-$E69A in ROM order.
pub fn heroFight(rng: *Rng, attack: u8, id: EnemyId, enemy_asleep: bool) FightResult {
    var result: FightResult = .{ .damage = 0 };
    if (id != .dragonlord1 and id != .dragonlord2 and rng.next() & 0x1F == 0) {
        result = .{ .damage = excellentDamage(rng, attack), .excellent = true };
    } else {
        result.damage = heroDamage(rng, attack, enemies[@backingInt(id)].agi);
        if (result.damage == 0) return result; // $E656: "missed", no dodge roll
    }
    if (!enemy_asleep) result.dodged = enemyDodges(rng, id); // $E66A BIT $DF / BVS
    return result;
}

pub fn heroHurt(rng: *Rng, id: EnemyId, more: bool) ?u8 {
    if (!spellLands(rng, id, .hurt)) return null;
    const r = rng.next() & 0x07;
    return if (more) r + 0x3A else r + 0x05;
}

pub fn enemyFlees(rng: *Rng, hero_str: u8, id: EnemyId) bool {
    if ((hero_str >> 1) < enemies[@backingInt(id)].str) return false; // no RNG call
    return rng.next() & 0x03 == 0;
}

pub fn heroEscapes(rng: *Rng, id: EnemyId, hero_agi: u8, enemy_asleep: bool) bool {
    if (enemy_asleep) return true;
    const n = @backingInt(id);
    const r0 = rng.next();
    const scale: u8 = if (n >= 0x23)
        r0
    else if (n >= 0x1E)
        r0 & 0x7F
    else if (n >= 0x14)
        (r0 & 0x3F) + (rng.next() & 0x1F) + rng.carry
    else
        rng.next() & 0x3F; // first roll discarded
    return enemyVsHero(rng, scale, enemies[n].agi, hero_agi);
}

/// $EEC7: 16-bit products, hero wins ties.
fn enemyVsHero(rng: *Rng, scale: u8, enemy_agi: u8, hero_agi: u8) bool {
    const enemy_side = @as(u16, scale) * enemy_agi;
    const hero_side = @as(u16, rng.next()) * hero_agi;
    return hero_side >= enemy_side;
}

pub fn heroGoesFirst(rng: *Rng, id: EnemyId, hero_agi: u8) bool {
    const scale = rng.next() & 0x3F;
    return enemyVsHero(rng, scale, enemies[@backingInt(id)].agi, hero_agi);
}

/// Menu and chest codes. Herbs and keys are counts; the rest live in the
/// 4-bit slots at $C1-$C4 as `code - 3` (1-14).
pub const Item = enum(u8) {
    herb = 0x02,
    magic_key,
    torch,
    fairy_water,
    wings,
    dragons_scale,
    fairy_flute,
    fighters_ring,
    erdricks_token,
    gwaelins_love,
    cursed_belt,
    silver_harp,
    death_necklace,
    stones_of_sunlight,
    staff_of_rain,
    rainbow_drop,

    fn slotId(self: Item) u8 {
        return @backingInt(self) - 3;
    }
};

/// Chests and shops refuse a 7th herb or key (a chest still counts as opened).
pub const max_herbs = 6;
pub const max_keys = 6;

pub const Inventory = struct {
    herbs: u8 = 0, // $C0
    keys: u8 = 0, // $BF
    slots: [4]u8 = @splat(0), // $C1-$C4: two items per byte, low nibble first

    /// $E01B: first empty nibble. False when all 8 are taken; the game then
    /// asks you to throw something away ($E07B).
    pub fn add(self: *Inventory, item: Item) bool {
        const id = item.slotId();
        for (&self.slots) |*b| {
            if (b.* & 0x0F == 0) {
                b.* = (b.* & 0xF0) | id;
                return true;
            }
            if (b.* & 0xF0 == 0) {
                b.* = (b.* & 0x0F) | (id << 4);
                return true;
            }
        }
        return false;
    }

    /// $E055.
    pub fn has(self: Inventory, item: Item) bool {
        const id = item.slotId();
        for (self.slots) |b| {
            if (b & 0x0F == id or b >> 4 == id) return true;
        }
        return false;
    }

    /// $E04B: clears the first match only.
    pub fn remove(self: *Inventory, item: Item) void {
        const id = item.slotId();
        for (&self.slots) |*b| {
            if (b.* & 0x0F == id) {
                b.* &= 0xF0;
                return;
            }
            if (b.* >> 4 == id) {
                b.* &= 0x0F;
                return;
            }
        }
    }

    /// $DF77: the ITEM menu, in order. Herbs and keys first, then slot order.
    pub fn menu(self: Inventory, buf: *[10]Item) []Item {
        var n: usize = 0;
        if (self.herbs != 0) {
            buf[n] = .herb;
            n += 1;
        }
        if (self.keys != 0) {
            buf[n] = .magic_key;
            n += 1;
        }
        for (self.slots) |b| {
            for ([_]u8{ b & 0x0F, b >> 4 }) |id| {
                if (id == 0) continue;
                buf[n] = @fromBackingInt(id + 3);
                n += 1;
            }
        }
        return buf[0..n];
    }
};

/// $CF bits set by using an item (bits 0-1 are HEALMORE/HURTMORE).
pub const Worn = struct {
    pub const rainbow_bridge: u8 = 0x08;
    pub const dragons_scale: u8 = 0x10;
    pub const fighters_ring: u8 = 0x20;
    pub const cursed_belt: u8 = 0x40;
    pub const death_necklace: u8 = 0x80;
};

/// $DFB9 / $DFD1 / $DFE7 / $E00A: set the worn bit. False if it was already
/// set ("already wearing"). The item stays in the inventory.
pub fn wear(cf: *u8, item: Item) bool {
    const bit: u8 = switch (item) {
        .dragons_scale => Worn.dragons_scale,
        .fighters_ring => Worn.fighters_ring,
        .cursed_belt => Worn.cursed_belt,
        .death_necklace => Worn.death_necklace,
        else => unreachable,
    };
    if (cf.* & bit != 0) return false;
    cf.* |= bit;
    return true;
}

pub fn cursed(cf: u8) bool {
    return cf & (Worn.cursed_belt | Worn.death_necklace) != 0;
}

/// $E0FA lists what can't be thrown away. Worn cursed items can't either.
pub fn droppable(item: Item, cf: u8) bool {
    return switch (item) {
        .herb, .magic_key, .fairy_flute, .erdricks_token, .gwaelins_love => false,
        .silver_harp, .stones_of_sunlight, .staff_of_rain, .rainbow_drop => false,
        .cursed_belt => cf & Worn.cursed_belt == 0,
        .death_necklace => cf & Worn.death_necklace == 0,
        else => true,
    };
}

pub const FieldItem = enum {
    herb, // herbs - 1, then applyHerb(healAmount(.herb))
    torch, // removed, Light.useTorch() (this also ends an active RADIANT)
    fairy_water, // removed, Repel.useFairyWater()
    wings, // removed, warp to return_dest
    wear, // wear(); kept
    harp, // silverHarp(), then that battle
    rainbow_bridge, // $CF |= Worn.rainbow_bridge; the drop is kept
    love, // gwaelinsLove()
    /// Torch outside a dungeon, Wings in a dungeon or the Dragonlord's room.
    /// Its own message; the item is kept.
    cant_use_here,
    /// Fairy Flute, Token, Stones, Staff, Harp off the overworld, Rainbow Drop
    /// in the wrong place.
    nothing_happened,
};

pub const Place = struct { map: u8, x: u8, y: u8 };

/// $DCEA: ITEM outside battle. The Magic Key is useKey().
pub fn fieldItem(item: Item, at: Place, cf: u8) FieldItem {
    return switch (item) {
        .herb => .herb,
        .magic_key => unreachable,
        .torch => if (mapKind(at.map) == .dungeon) .torch else .cant_use_here,
        .fairy_water => .fairy_water,
        .wings => if (mapKind(at.map) == .dungeon or at.map == 0x06) .cant_use_here else .wings,
        .dragons_scale, .fighters_ring, .cursed_belt, .death_necklace => .wear,
        .silver_harp => if (at.map == 0x01) .harp else .nothing_happened,
        .rainbow_drop => if (at.map == 0x01 and at.x == 0x41 and at.y == 0x31 and
            cf & Worn.rainbow_bridge == 0) .rainbow_bridge else .nothing_happened,
        .gwaelins_love => .love,
        .fairy_flute, .erdricks_token, .stones_of_sunlight, .staff_of_rain => .nothing_happened,
    };
}

pub const BattleItem = enum {
    herb,
    /// Puts the Golem to sleep, otherwise nothing. Uses the turn.
    flute,
    /// Plays, nothing else. Uses the turn.
    harp,
    wear, // uses the turn
    /// "Cannot be used in battle": back to the command menu, turn not used.
    refused,
};

/// $E7D6.
pub fn battleItem(item: Item) BattleItem {
    return switch (item) {
        .herb => .herb,
        .fairy_flute => .flute,
        .silver_harp => .harp,
        .dragons_scale, .fighters_ring, .cursed_belt, .death_necklace => .wear,
        else => .refused,
    };
}

/// $E806: no roll. The Golem then skips its next wake roll, like SLEEP.
pub fn fluteSleeps(enemy: EnemyId) bool {
    return enemy == .golem;
}

/// $600C-$601B: doors opened since you last arrived on the overworld.
pub const DoorLog = struct {
    slots: [8][2]u8 = @splat(.{ 0, 0 }),

    /// Bank 0 $AD4D: a door tile at a logged (x, y) is drawn open.
    /// Only coordinates are compared, not the map.
    pub fn opened(self: DoorLog, x: u8, y: u8) bool {
        for (self.slots) |slot| {
            if (slot[0] == x and slot[1] == y) return true;
        }
        return false;
    }

    /// Bank 0 $AF2B: on arriving at the overworld. The chest log is cleared there too.
    pub fn clear(self: *DoorLog) void {
        self.* = .{};
    }
};

pub const KeyResult = enum { no_door, no_key, opened, lost };

/// $DC42. `doors` says whether a closed door is up, down, left and right of
/// the hero, which is the order the ROM checks.
pub fn useKey(inv: *Inventory, log: *DoorLog, x: u8, y: u8, doors: [4]bool) KeyResult {
    const offsets = [4][2]i8{ .{ 0, -1 }, .{ 0, 1 }, .{ -1, 0 }, .{ 1, 0 } };
    const dir = std.mem.findScalar(bool, &doors, true) orelse return .no_door;
    if (inv.keys == 0) return .no_key;
    inv.keys -= 1; // spent before the free-slot search
    const dx = x +% @as(u8, @bitCast(offsets[dir][0]));
    const dy = y +% @as(u8, @bitCast(offsets[dir][1]));
    for (&log.slots) |*slot| {
        if (slot[0] == 0) { // $DCAC: only x is tested
            slot.* = .{ dx, dy };
            return .opened;
        }
    }
    return .lost; // 8 doors already open: the key is gone, the door stays shut
}

pub const LoveReport = struct {
    /// null at level 30, which gets a different line.
    xp_to_next: ?u16,
    /// Overworld only: hero minus Tantegel (43, 43). The ROM prints each axis
    /// as a distance with a direction word picked by the sign ($DF2E-$DF6C).
    from_tantegel: ?struct { dx: i16, dy: i16 },
};

/// $DF11.
pub fn gwaelinsLove(xp: u16, at: Place) LoveReport {
    return .{
        .xp_to_next = xpToNext(xp),
        .from_tantegel = if (at.map != 0x01) null else .{
            .dx = @as(i16, at.x) - 0x2B,
            .dy = @as(i16, at.y) - 0x2B,
        },
    };
}

