/// Bank 0 $9947: price by shop index. 0-6 weapons, 7-13 armor, 14-16
/// shields (equipment value - 1 within each), then item code + 15.
/// Erdrick's Sword and Armor are listed at 2 gold but no shop stocks them.
pub const prices = [33]u16{
    10, 60, 180, 560, 1500, 9800, 2, // weapons
    20, 70, 300, 1000, 3000, 7700, 2, // armor
    90, 800, 14800, // shields
    24, 53, 8, 38, 70, 20, 0, 30, 0, 0, 360, 0, 2400, 0, 0, 0, // items 0x02-0x11
};

/// $9991: what each shop sells, as shop indexes (0xFD-separated in the ROM).
/// Which town uses which list is NPC data.
pub const shop_stock = [12][]const u8{
    &.{ 2, 3, 10, 11, 14 },
    &.{ 0, 1, 2, 7, 8, 14 },
    &.{ 1, 2, 3, 8, 9, 10, 15 },
    &.{ 0, 1, 2, 8, 9, 15 },
    &.{ 3, 4, 11, 12 },
    &.{ 5, 16 },
    &.{ 2, 3, 4, 10, 11, 12 },
    &.{ 17, 19, 22, 21 },
    &.{ 17, 19, 22 },
    &.{ 17, 19, 22 },
    &.{ 17, 19 },
    &.{ 22, 21 },
};

pub const key_prices = [3]u8{ 98, 53, 85 }; // $9989, by key seller
pub const inn_prices = [5]u8{ 20, 6, 25, 100, 55 }; // $998C, by innkeeper
pub const fairy_water_price = 38; // $D843

/// One NPC from bank 0 $9734 (moving) or $974C (stationary).
pub const Npc = struct {
    x: u8,
    y: u8,
    dialogue: u8,
    moves: bool,
    /// RAM slot: $51 + slot * 3. Moving NPCs use 0-9, stationary ones 10-19.
    slot: u8,
    /// The sprite: the top 3 bits of the x byte. Only for drawing; the rules
    /// never read it, and romcheck doesn't check what each value looks like.
    sprite: u3 = 0,
};

/// The NPCs of map 4-0x0E as the TALK code reads them (index map - 4), from
/// Maps.npcs (bank 0 $9734 and $974C, ended by 0xFF or ten entries).
/// `df` is $DF: in the throne room, Gwaelin (stationary slot 13) is only
/// there once she's been returned (bank 0 $B01A blanks her slot otherwise).
pub fn npcs(maps: *const Maps, map: u8, df: u8, buf: *[20]Npc) []Npc {
    if (map < 0x04 or map > 0x0E) return buf[0..0];
    var n: usize = 0;
    for (maps.npcs[map - 4], [2]bool{ true, false }, [2]u8{ 0, 10 }) |r, moves, first| {
        for (r.rec[0..r.len], first..) |rec, slot| {
            if (map == 0x05 and slot == 13 and df & Quest.princess_returned == 0) continue;
            buf[n] = .{ .x = rec[0] & 0x1F, .y = rec[1] & 0x1F, .dialogue = rec[2], .moves = moves, .slot = @intCast(slot), .sprite = @intCast(rec[0] >> 5) };
            n += 1;
        }
    }
    return buf[0..n];
}

pub const NpcService = union(enum) {
    /// shop_stock index 0-6: weapons and armor ($D553).
    equipment: u8,
    /// shop_stock index 7-11: tools ($D6A7).
    items: u8,
    /// key_prices index ($D7ED).
    keys: u8,
    /// 38 gold ($D843).
    fairy_water,
    /// inn_prices index ($D895).
    inn: u8,
    /// HP untouched, MP to max ($D2CF).
    restore_mp,
    /// removeCurse ($D26A). Brecconary.
    remove_curse,
    /// staffShrine ($D2F8). The north shrine.
    staff_shrine,
    /// rainbowShrine ($D345). The south shrine.
    rainbow_shrine,
    /// dragonlordOffer ($D4A4 -> $D4AB). The Dragonlord, on his throne.
    dragonlord,
    /// Anything else is dialogue.
    talk,
};

/// $D16A. With the Dragonlord beaten, TALK never gets here ($D134).
pub fn npcService(dialogue: u8, story: u8) NpcService {
    if (story & Story.dragonlord_beaten != 0) return .talk;
    return switch (dialogue) {
        0x00...0x06 => .{ .equipment = dialogue },
        0x07...0x0B => .{ .items = dialogue },
        0x0C...0x0E => .{ .keys = dialogue - 0x0C },
        0x0F, 0x10 => .fairy_water,
        0x11...0x15 => .{ .inn = dialogue - 0x11 },
        0x67 => .remove_curse,
        0x6A => .restore_mp,
        0x6C => .staff_shrine,
        0x6D => .rainbow_shrine,
        0x70 => .dragonlord,
        else => .talk,
    };
}

pub fn itemPrice(item: Item) u16 {
    return prices[@backingInt(item) + 15];
}

/// $D589-$D63C: buy shop index 0-16. False (nothing changes) if gold < price:
/// the check uses the full price, before the trade-in. The piece you had is
/// taken in for half its price, rounded down, and gold sticks at 65535.
pub fn buyEquipment(gold: *u16, equip: *Equipment, index: u8) bool {
    const price = prices[index];
    if (gold.* < price) return false;
    const base: u8, const current: u8 = if (index < 7)
        .{ 0, equip.weapon }
    else if (index < 14)
        .{ 7, equip.armor }
    else
        .{ 14, equip.shield };
    const trade_in: u16 = if (current == 0) 0 else prices[base + current - 1] / 2;
    gold.* = (gold.* - price) +| trade_in;
    const value = index - base + 1;
    if (index < 7) {
        equip.weapon = @intCast(value);
    } else if (index < 14) {
        equip.armor = @intCast(value);
    } else {
        equip.shield = @intCast(value);
    }
    return true;
}

pub const BuyResult = enum { bought, not_enough_gold, full };

/// $D6DB: item shops and the Fairy Water seller ($D85B). Gold is checked
/// first; a 7th herb or a 9th item is refused and costs nothing.
pub fn buyItem(gold: *u16, inv: *Inventory, item: Item, price: u16) BuyResult {
    if (gold.* < price) return .not_enough_gold;
    if (item == .herb) {
        if (inv.herbs == max_herbs) return .full;
        inv.herbs += 1;
    } else if (!inv.add(item)) return .full;
    gold.* -= price;
    return .bought;
}

/// $D80B: key sellers check the key count before the gold.
pub fn buyKey(gold: *u16, inv: *Inventory, price: u8) BuyResult {
    if (inv.keys == max_keys) return .full;
    if (gold.* < price) return .not_enough_gold;
    gold.* -= price;
    inv.keys += 1;
    return .bought;
}

pub const SellResult = enum { sold, worthless, cursed };

/// $D763: half the price, rounded down; gold sticks at 65535. Price 0 items
/// (quest items) can't be sold, and neither can a cursed item you're wearing.
pub fn sell(gold: *u16, inv: *Inventory, item: Item, cf: u8) SellResult {
    const price = itemPrice(item);
    if (price == 0) return .worthless;
    switch (item) {
        .magic_key => inv.keys -= 1,
        .herb => inv.herbs -= 1,
        .cursed_belt, .death_necklace => {
            if (!droppable(item, cf)) return .cursed;
            inv.remove(item);
        },
        else => inv.remove(item),
    }
    gold.* +|= price / 2;
    return .sold;
}

/// $D8B3: pay, then HP and MP to max ($D8E3). Nothing else changes.
pub fn stayAtInn(gold: *u16, price: u8, hp: *u8, mp: *u8, max_hp: u8, max_mp: u8) bool {
    if (gold.* < price) return false;
    gold.* -= price;
    hp.* = max_hp;
    mp.* = max_mp;
    return true;
}

pub const Revived = struct {
    gold: u16,
    hp: u8,
    mp: u8,
    at: Warp,
};

/// $EDB4 then $CB47: gold halved (rounded down), $DF bit 0 cleared, REPEL
/// ended, and you wake in the throne room (map 5) at (3, 4) with full HP and
/// MP. XP, items and equipment are kept. Cursed: 1 HP, MP left as it was, and
/// $EDE1 then puts you outside the castle at (43, 43).
pub fn die(gold: u16, mp: u8, max_hp: u8, max_mp: u8, cf: u8) Revived {
    if (cursed(cf)) return .{ .gold = gold >> 1, .hp = 1, .mp = mp, .at = .{ .map = 0x01, .x = 0x2B, .y = 0x2B } };
    return .{ .gold = gold >> 1, .hp = max_hp, .mp = max_mp, .at = .{ .map = 0x05, .x = 0x03, .y = 0x04 } };
}

test "the trade-in comes after the gold check" {
    var gold: u16 = 170;
    var equip: Equipment = .{ .shield = 0, .armor = 0, .weapon = 2 }; // Club
    try std.testing.expect(!buyEquipment(&gold, &equip, 2)); // Copper Sword: 180 > 170
    gold = 180;
    try std.testing.expect(buyEquipment(&gold, &equip, 2));
    try std.testing.expectEqual(30, gold); // 180 - 180 + 60 / 2
    try std.testing.expectEqual(3, equip.weapon);
}

test "selling" {
    var gold: u16 = 0;
    var inv: Inventory = .{ .herbs = 1 };
    _ = inv.add(.cursed_belt);
    try std.testing.expectEqual(SellResult.cursed, sell(&gold, &inv, .cursed_belt, Worn.cursed_belt));
    try std.testing.expectEqual(SellResult.sold, sell(&gold, &inv, .herb, 0));
    try std.testing.expectEqual(12, gold);
    try std.testing.expectEqual(SellResult.worthless, sell(&gold, &inv, .erdricks_token, 0));
}

/// $E365: base + (RAND & mask). Always one RNG call, even when mask is 0.
pub fn chestGold(rng: *Rng, base: u16, mask: u8) u16 {
    return base + (rng.next() & mask);
}

pub const GoldChest = struct { base: u16, mask: u8 };

pub fn goldChest(id: u8) ?GoldChest {
    return switch (id) {
        0x0E => .{ .base = 0x64, .mask = 0x1F }, // when the necklace doesn't drop
        0x12 => .{ .base = 0x05, .mask = 0x0F },
        0x13 => .{ .base = 0x06, .mask = 0x07 },
        0x14 => .{ .base = 0x0A, .mask = 0x07 },
        0x15 => .{ .base = 0x1F4, .mask = 0xFF },
        0x16 => .{ .base = 120, .mask = 0x00 },
        else => null,
    };
}

pub const MountainCave = union(enum) { death_necklace, gold: u16 };

/// $E254: $DF bit 2 records that the necklace was already found.
pub fn mountainCaveChest(rng: *Rng, necklace_found: bool) MountainCave {
    if (!necklace_found and rng.next() & 0x1F == 0) return .death_necklace;
    return .{ .gold = chestGold(rng, 0x64, 0x1F) };
}

pub const ChestLog = struct {
    slots: [8][2]u8 = @splat(.{ 0, 0 }), // $601C..$602B

    pub fn record(self: *ChestLog, x: u8, y: u8) void {
        for (&self.slots) |*slot| {
            if (slot[0] | slot[1] == 0) {
                slot.* = .{ x, y };
                return;
            }
        }
        // Full: dropped. This is the bug; keep it.
    }

    pub fn opened(self: ChestLog, x: u8, y: u8) bool {
        for (self.slots) |slot| {
            if (slot[0] == x and slot[1] == y) return true;
        }
        return false;
    }

    /// Call when arriving on the overworld (bank 0 $AF2B), not on other map changes or death.
    pub fn clear(self: *ChestLog) void {
        self.* = .{};
    }

    /// Entering the throne room fills the last three slots.
    pub fn markThroneRoom(self: *ChestLog, chests: [3][2]u8) void {
        self.slots[5..8].* = chests;
    }
};

test "a ninth chest never registers" {
    var log: ChestLog = .{};
    var i: u8 = 1;
    while (i <= 8) : (i += 1) log.record(i, i);
    log.record(20, 20);
    try std.testing.expect(!log.opened(20, 20));
}

pub const Chest = struct { map: u8, x: u8, y: u8, contents: u8 };

