/// $E202: the first chest at this spot. TAKE first checks the tile is a chest
/// ($E1F3); an opened chest reads as brick, so it never gets here.
pub fn chestAt(at: Warp) ?u8 {
    for (chest_table) |c| if (c.map == at.map and c.x == at.x and c.y == at.y) return c.contents;
    return null;
}

pub const Taken = union(enum) {
    herb,
    key,
    /// Six herbs or keys already: nothing, but the chest counts as opened.
    full,
    item: Item,
    /// No free slot: the throw-away prompt ($E07B) for this item.
    no_room: Item,
    gold: u16,
    /// Into the weapon slot ($BE |= 0xE0), no trade-in.
    erdricks_sword,
    /// You have it, or what it turns into: nothing.
    already,
    /// Erdrick's Tablet: a message.
    tablet,
};

/// $E221: what a chest with `contents` does. Every result logs the chest as
/// opened (ChestLog.record, $E39A), `full`, `already` and `no_room` included.
pub fn takeChest(rng: *Rng, contents: u8, inv: *Inventory, gold: *u16, equipment: *u8, df: *u8) Taken {
    switch (contents) {
        0x03 => {
            if (inv.keys == max_keys) return .full;
            inv.keys += 1;
            return .key;
        },
        0x02 => {
            if (inv.herbs == max_herbs) return .full;
            inv.herbs += 1;
            return .herb;
        },
        0x0E => switch (mountainCaveChest(rng, df.* & Quest.necklace_found != 0)) {
            .death_necklace => {
                df.* |= Quest.necklace_found;
                return chestItem(inv, .death_necklace);
            },
            .gold => |n| {
                gold.* +|= n;
                return .{ .gold = n };
            },
        },
        0x11 => {
            if (equipment.* & 0xE0 == 0xE0) return .already;
            equipment.* |= 0xE0;
            return .erdricks_sword;
        },
        0x0D => return if (inv.has(.silver_harp) or inv.has(.staff_of_rain) or inv.has(.rainbow_drop)) .already else chestItem(inv, .silver_harp),
        0x0F => return if (inv.has(.stones_of_sunlight) or inv.has(.rainbow_drop)) .already else chestItem(inv, .stones_of_sunlight),
        0x12...0x16 => {
            const g = goldChest(contents).?;
            const n = chestGold(rng, g.base, g.mask);
            gold.* +|= n; // $E384: stops at 65535
            return .{ .gold = n };
        },
        0x04...0x0C, 0x10 => return chestItem(inv, @fromBackingInt(contents)),
        else => return .tablet, // $E349: 0x17 and up
    }
}

fn chestItem(inv: *Inventory, item: Item) Taken {
    return if (inv.add(item)) .{ .item = item } else .{ .no_room = item };
}

pub const Searched = union(enum) {
    nothing,
    /// "There is a treasure chest here": you're standing on one.
    chest,
    item: Item,
    no_room: Item,
    /// Into the armor slot ($BE |= 0x1C), no trade-in.
    erdricks_armor,
    /// Charlock 1F (10, 3).
    hint,
    charlock_stairs,
};

/// $E103: SEARCH at `at`, standing on `tile`.
pub fn search(at: Warp, tile: Tile, inv: *Inventory, equipment: *u8, cf: *u8) Searched {
    if (at.map == 0x01 and at.x == 0x53 and at.y == 0x71) return searchItem(inv, .erdricks_token);
    if (at.map == 0x07 and at.x == 0x09 and at.y == 0x06) return searchItem(inv, .fairy_flute);
    if (at.map == 0x03 and at.x == 0x12 and at.y == 0x0C) {
        if (equipment.* & 0x1C == 0x1C) return .nothing;
        equipment.* |= 0x1C;
        return .erdricks_armor;
    }
    if (at.map == 0x02 and at.x == 0x0A) {
        if (at.y == 0x03) return .hint;
        if (at.y == 0x01 and cf.* & charlock_stairs_found == 0) {
            cf.* |= charlock_stairs_found;
            return .charlock_stairs;
        }
    }
    return if (tile == .chest) .chest else .nothing; // $E1C8
}

fn searchItem(inv: *Inventory, item: Item) Searched {
    if (inv.has(item)) return .nothing;
    return if (inv.add(item)) .{ .item = item } else .{ .no_room = item };
}

pub const StaffShrine = enum { have_it, hint, harp_taken };

/// $D2F8, the north shrine's old man. harp_taken: he leaves (NPC slot $6F
/// cleared), so the Staff of Rain's chest at (3, 4) can be reached.
pub fn staffShrine(inv: *Inventory) StaffShrine {
    if (inv.has(.rainbow_drop) or inv.has(.staff_of_rain)) return .have_it;
    if (!inv.has(.silver_harp)) return .hint;
    inv.remove(.silver_harp);
    return .harp_taken;
}

pub const RainbowShrine = enum { have_it, kicked_out, missing, rainbow_drop };

/// $D345, the south shrine. kicked_out: no Token, so out through the
/// shrine's exit ($B228). The Token is kept.
pub fn rainbowShrine(inv: *Inventory) RainbowShrine {
    if (inv.has(.rainbow_drop)) return .have_it;
    if (!inv.has(.erdricks_token)) return .kicked_out;
    if (!inv.has(.stones_of_sunlight) or !inv.has(.staff_of_rain)) return .missing;
    inv.remove(.stones_of_sunlight);
    inv.remove(.staff_of_rain);
    _ = inv.add(.rainbow_drop);
    return .rainbow_drop;
}

/// $D26A, Brecconary's (24, 10). False if you aren't cursed.
pub fn removeCurse(inv: *Inventory, cf: *u8) bool {
    if (cf.* & (Worn.cursed_belt | Worn.death_necklace) == 0) return false;
    if (cf.* & Worn.death_necklace != 0) inv.remove(.death_necklace);
    if (cf.* & Worn.cursed_belt != 0) inv.remove(.cursed_belt);
    cf.* &= 0x3F;
    return true;
}

/// $D051: TALK facing the princess tile (0x17) in the Swamp Cave.
pub const gwaelin: Warp = .{ .map = 0x15, .x = 5, .y = 18 };

test "the Silver Harp chest won't refill once you've traded the harp" {
    var rng: Rng = .init(0);
    var inv: Inventory = .{};
    var gold: u16 = 0;
    var equip: u8 = 0;
    var df: u8 = 0;
    try std.testing.expectEqual(Taken{ .item = .silver_harp }, takeChest(&rng, 0x0D, &inv, &gold, &equip, &df));
    try std.testing.expectEqual(StaffShrine.harp_taken, staffShrine(&inv));
    _ = inv.add(.staff_of_rain);
    try std.testing.expectEqual(Taken.already, takeChest(&rng, 0x0D, &inv, &gold, &equip, &df));
}

/// The guide's letter value: the low nibble of the letter's name tile.
pub fn nameValue(c: u8) ?u8 {
    return if (nameTile(c)) |t| t & 0x0F else null;
}

/// Name tile codes, as saved and summed: 0x00-0x09 digits, 0x0A-0x23 a-z,
/// 0x24-0x3D A-Z, punctuation 0x40-0x4F, 0x60 space.
pub fn nameTile(c: u8) ?u8 {
    return switch (c) {
        '0'...'9' => c - '0',
        'a'...'z' => c - 'a' + 0x0A,
        'A'...'Z' => c - 'A' + 0x24,
        '\'' => 0x40,
        '.' => 0x47,
        ',' => 0x48,
        '-' => 0x49,
        '?' => 0x4B,
        '!' => 0x4C,
        ')' => 0x4E,
        '(' => 0x4F,
        ' ' => 0x60,
        else => null,
    };
}

/// Bank 1 $AE48 fills the name entry buffer with spaces, so a short name is
/// padded with 0x60, whose low nibble (the only part that counts) is 0.
pub const name_pad: u8 = 0x60;

/// $F085: the sum of the first four tiles. applyName() uses only bits 0-3.
pub fn nameSum(name: []const u8) ?u8 {
    var sum: u8 = 0;
    for (0..4) |i| sum +%= if (i < name.len) nameTile(name[i]) orelse return null else name_pad;
    return sum;
}

pub const Stats = struct { str: u8, agi: u8, hp: u8, mp: u8 };

fn reduceStat(value: u8, bonus: u8) u8 {
    return @truncate(@as(u16, value) * 9 / 10 + bonus);
}

pub fn applyName(base: Stats, sum: u8) Stats {
    const bonus = (sum >> 2) & 0x03;
    var s = base;
    if (sum & 0x01 == 0) {
        s.str = reduceStat(s.str, bonus);
    } else if (s.mp != 0) {
        s.mp = reduceStat(s.mp, bonus);
    }
    if (sum & 0x02 == 0) {
        s.agi = reduceStat(s.agi, bonus);
    } else {
        s.hp = reduceStat(s.hp, bonus);
    }
    return s;
}

/// Base stats by level (index 0 = level 1).
