/// $F35B: total XP needed for each level (index 0 = level 1).
pub const xp_table = [30]u16{
    0,     7,     23,    47,    110,   220,   450,   800,   1300,  2000,
    2900,  4000,  5500,  7500,  10000, 13000, 16000, 19000, 22000, 26000,
    30000, 34000, 38000, 42000, 46000, 50000, 54000, 58000, 62000, 65535,
};

/// $C156 / $F050: the highest level whose threshold is <= XP.
/// The ROM counts down from 30 and stops at 1 without comparing entry 0.
pub fn levelFor(xp: u16) u8 {
    var level: u8 = 30;
    while (level > 1 and xp < xp_table[level - 1]) level -= 1;
    return level;
}

/// $F134: "XP needed" on the status window. The ROM skips the call at level 30
/// ($EDF2), because the table has no 31st entry to read.
pub fn xpToNext(xp: u16) ?u16 {
    const level = levelFor(xp);
    if (level == 30) return null;
    return xp_table[level] - xp;
}

/// $EA17 (XP) and $EA50 (gold): a 16-bit add that sticks at 65535.
pub fn addCapped(total: u16, gain: u8) u16 {
    return total +| gain;
}

/// $BE: one byte holds all three equipment slots.
pub const Equipment = packed struct(u8) {
    shield: u2, // bits 0-1
    armor: u3, // bits 2-4
    weapon: u3, // bits 5-7
};

/// Bank 0 $99CF / $99D7 / $99DF.
pub const weapon_attack = [8]u8{ 0, 2, 4, 10, 15, 20, 28, 40 };
pub const armor_defense = [8]u8{ 0, 2, 4, 10, 16, 24, 24, 28 };
pub const shield_defense = [4]u8{ 0, 4, 10, 20 };

pub const Hero = struct {
    level: u8, // $C7
    stats: Stats, // $C8-$CB (HP and MP here are the maximums)
    attack: u8, // $CC
    defense: u8, // $CD
    spells: SpellSet,
};

/// $F0CD: ATK and DEF. 8-bit adds with no carry check, like the ROM.
pub fn combatStats(s: Stats, equip: Equipment, dragon_scale: bool) struct { attack: u8, defense: u8 } {
    var def = (s.agi >> 1) +% armor_defense[equip.armor] +% shield_defense[equip.shield];
    if (dragon_scale) def +%= 2; // $CF bit 4
    return .{ .attack = s.str +% weapon_attack[equip.weapon], .defense = def };
}

/// $F050: rebuild every derived value from XP, the name sum and equipment.
/// Current HP and MP ($C5/$C6) aren't touched. No RNG calls.
pub fn heroFor(xp: u16, name_sum: u8, equip: Equipment, dragon_scale: bool) Hero {
    const level = levelFor(xp);
    const s = applyName(level_stats[level - 1], name_sum);
    const c = combatStats(s, equip, dragon_scale);
    return .{ .level = level, .stats = s, .attack = c.attack, .defense = c.defense, .spells = spellsAt(level) };
}

/// What the victory text prints after $F050 runs ($EA63).
pub const LevelUp = struct {
    level: u8,
    /// The ROM prints STR, AGI and MP only when the gain is non-zero. HP always prints.
    str: u8,
    agi: u8,
    hp: u8,
    mp: u8,
    /// $EAE6 checks the *new* level against the learn levels, so skipping
    /// past a spell level in one fight teaches the spell without the message.
    spell_message: bool,
};

pub fn levelUp(before: Hero, after: Hero) ?LevelUp {
    if (after.level == before.level) return null;
    return .{
        .level = after.level,
        .str = after.stats.str -% before.stats.str,
        .agi = after.stats.agi -% before.stats.agi,
        .hp = after.stats.hp -% before.stats.hp,
        .mp = after.stats.mp -% before.stats.mp,
        .spell_message = std.mem.findScalar(u8, &learn_level, after.level) != null,
    };
}

test "level thresholds" {
    try std.testing.expectEqual(1, levelFor(6));
    try std.testing.expectEqual(2, levelFor(7));
    try std.testing.expectEqual(29, levelFor(65534));
    try std.testing.expectEqual(30, levelFor(65535));
    try std.testing.expectEqual(16, xpToNext(7).?);
    try std.testing.expectEqual(null, xpToNext(65535));
    try std.testing.expectEqual(65535, addCapped(65500, 200));
}

test "skipping a spell level in one fight: spell, but no message" {
    const bare: Equipment = .{ .shield = 0, .armor = 0, .weapon = 0 };
    const up = levelUp(heroFor(23, 0, bare, false), heroFor(110, 0, bare, false)).?;
    try std.testing.expectEqual(5, up.level);
    try std.testing.expect(heroFor(110, 0, bare, false).spells.contains(.hurt)); // learned at 4
    try std.testing.expect(!up.spell_message);
}

/// Menu order, and bit order in $CE (bits 0-7) and $CF (bits 0-1).
pub const Spell = enum(u4) { heal, hurt, sleep, radiant, stopspell, outside, @"return", repel, healmore, hurtmore };

/// Bank 0 $9D53.
pub const mp_cost = [10]u8{ 4, 2, 2, 3, 2, 6, 8, 2, 10, 5 };

/// The first level whose row in bank 1 $A0CD has the spell's bit set.
pub const learn_level = [10]u8{ 3, 4, 7, 9, 10, 12, 13, 15, 17, 19 };

pub const SpellSet = struct {
    bits: u10 = 0, // $CE | ($CF & 3) << 8

    pub fn contains(self: SpellSet, spell: Spell) bool {
        return self.bits & (@as(u10, 1) << @backingInt(spell)) != 0;
    }
};

/// Bank 1 $99B4 copies the level row's spell bytes. $CF's low two bits are ORed in
/// because its high bits are item flags (bit 4 Dragon's Scale, bits 6-7 curses).
pub fn spellsAt(level: u8) SpellSet {
    var set: SpellSet = .{};
    for (learn_level, 0..) |lv, i| {
        if (level >= lv) set.bits |= @as(u10, 1) << @intCast(i);
    }
    return set;
}

/// $16, set from the map number at bank 0 $B02E.
pub const MapKind = enum(u8) { overworld = 0x00, town = 0x10, dungeon = 0x20 };

/// Map 1 is the overworld, 0x0F and up are caves and Charlock's basements, and
/// everything else (towns, castles, shrines, Charlock 1F, the Dragonlord's room) is a town.
pub fn mapKind(map: u8) MapKind {
    if (map >= 0x0F) return .dungeon;
    if (map == 0x01) return .overworld;
    return .town;
}

/// $DB85: "Not enough MP" leaves MP alone. Otherwise the cost is paid up front.
pub fn payMp(mp: *u8, spell: Spell) bool {
    const cost = mp_cost[@backingInt(spell)];
    if (mp.* < cost) return false;
    mp.* -= cost;
    return true;
}

pub const Warp = struct { map: u8, x: u8, y: u8 };

/// $DB00: one tile west of Tantegel's overworld entrance (43, 43).
pub const return_dest: Warp = .{ .map = 0x01, .x = 0x2A, .y = 0x2B };

/// $DA9F: OUTSIDE picks an exit by map number (warp table $F3C8).
pub fn outsideDest(map: u8) ?Warp {
    return switch (map) {
        0x1C...0xFF => .{ .map = 0x01, .x = 0x1C, .y = 0x0C }, // Erdrick's Cave
        0x18...0x1B => .{ .map = 0x09, .x = 0x13, .y = 0x00 }, // Garin's Grave -> Garinham
        0x16, 0x17 => .{ .map = 0x01, .x = 0x1D, .y = 0x39 }, // Mountain Cave
        0x15 => .{ .map = 0x01, .x = 0x68, .y = 0x2C }, // Swamp Cave: always the north end
        0x06, 0x0F...0x14 => .{ .map = 0x01, .x = 0x30, .y = 0x30 }, // Charlock
        else => null,
    };
}

pub const FieldCast = union(enum) {
    not_enough_mp,
    /// "But nothing happened." The MP is still spent.
    nothing_happened,
    heal, // applyHeal with healAmount(.heal)
    healmore,
    radiant, // Light.radiant()
    repel, // $DB = 0xFF
    warp: Warp, // OUTSIDE or RETURN
};

/// $DA34: the SPELL command outside battle. MP is paid before the spell
/// checks where you are.
pub fn fieldCast(mp: *u8, spell: Spell, map: u8) FieldCast {
    if (!payMp(mp, spell)) return .not_enough_mp;
    return switch (spell) {
        .heal => .heal,
        .healmore => .healmore,
        .repel => .repel,
        .radiant => if (mapKind(map) == .dungeon) .radiant else .nothing_happened,
        .outside => if (outsideDest(map)) |w| .{ .warp = w } else .nothing_happened,
        .@"return" => if (mapKind(map) == .dungeon or map == 0x06)
            .nothing_happened
        else
            .{ .warp = return_dest },
        .hurt, .sleep, .stopspell, .hurtmore => .nothing_happened,
    };
}

pub const BattleCast = enum {
    /// RADIANT, OUTSIDE, RETURN, REPEL: refused, no MP spent, back to the command menu.
    field_only,
    /// No MP spent, back to the command menu. The turn isn't used.
    not_enough_mp,
    /// The hero is under STOPSPELL ($DF bit 4): MP spent, turn lost.
    stopped,
    /// MP spent. Resolve with applyHeal / heroHurt / spellLands.
    cast,
};

/// $E6ED-$E720.
pub fn battleCast(mp: *u8, spell: Spell, hero_stopped: bool) BattleCast {
    switch (spell) {
        .radiant, .outside, .@"return", .repel => return .field_only,
        else => {},
    }
    if (!payMp(mp, spell)) return .not_enough_mp;
    return if (hero_stopped) .stopped else .cast;
}

test "spells by level" {
    try std.testing.expectEqual(0, spellsAt(2).bits);
    try std.testing.expect(spellsAt(3).contains(.heal));
    try std.testing.expect(!spellsAt(18).contains(.hurtmore));
    try std.testing.expectEqual(0x3FF, spellsAt(19).bits);
}

test "casting rules" {
    var mp: u8 = 10;
    try std.testing.expectEqual(FieldCast.nothing_happened, fieldCast(&mp, .hurt, 0x01));
    try std.testing.expectEqual(8, mp); // spent anyway
    try std.testing.expectEqual(FieldCast.nothing_happened, fieldCast(&mp, .@"return", 0x06));
    try std.testing.expectEqual(0, mp);
    try std.testing.expectEqual(FieldCast.not_enough_mp, fieldCast(&mp, .heal, 0x01));

    mp = 6;
    const out = fieldCast(&mp, .outside, 0x06); // works in the Dragonlord's room
    try std.testing.expectEqual(Warp{ .map = 0x01, .x = 0x30, .y = 0x30 }, out.warp);

    mp = 1;
    try std.testing.expectEqual(BattleCast.field_only, battleCast(&mp, .repel, false));
    try std.testing.expectEqual(BattleCast.not_enough_mp, battleCast(&mp, .hurt, false));
    mp = 2;
    try std.testing.expectEqual(BattleCast.stopped, battleCast(&mp, .hurt, true));
    try std.testing.expectEqual(0, mp);
}

/// $DF bits outside battle. Bits 4-7 are battle status (hero STOPSPELLed,
/// enemy STOPSPELLed, enemy asleep, hero asleep) and are cleared at battle start.
pub const Quest = struct {
    pub const carrying_princess: u8 = 0x01; // set when she joins, cleared on death
    pub const princess_returned: u8 = 0x02; // set (and bit 0 cleared) at the king
    pub const necklace_found: u8 = 0x04; // the Mountain Cave B2 roll is spent
    /// Set on loading any map but the throne room. With it set, entering the
    /// throne room marks its 3 chests and its door as opened (bank 0 $AF3C).
    pub const left_throne_room: u8 = 0x08;
};

/// $CF bit 2 (bits 3-7 are in Worn, 0-1 are spells).
pub const charlock_stairs_found: u8 = 0x04;

/// The 0x20-byte record in each SRAM copy and the $6048 working buffer.
pub const SaveRecord = struct {
    xp: u16, // $BA
    gold: u16, // $BC
    slots: [4]u8, // $C1-$C4
    keys: u8, // $BF; saved as min(keys & 0x0F, 6)
    herbs: u8, // $C0
    equipment: u8, // $BE
    cf: u8, // spells HEALMORE/HURTMORE, stairs, bridge, worn items
    df: u8, // Quest
    e4: u8, // Story
    name: [8]u8, // tile codes, $B5-$B8 then $64C9-$64C6 order reversed below
    message_speed: u8, // $E5
    hp: u8, // $C5
    mp: u8, // $C6
    /// $6045[slot]: 0x78 = refill HP/MP on the next start (new game), else 0xAB.
    start_flag: u8,

    /// $FA18: record bytes 0x00-0x1D, then $FBE0 adds the CRC at 0x1E.
    pub fn encode(self: SaveRecord) [32]u8 {
        var b: [32]u8 = undefined;
        std.mem.writeInt(u16, b[0x00..0x02], self.xp, .little);
        std.mem.writeInt(u16, b[0x02..0x04], self.gold, .little);
        b[0x04..0x08].* = self.slots;
        b[0x08] = @min(self.keys & 0x0F, 6);
        b[0x09] = self.herbs;
        b[0x0A] = self.equipment;
        b[0x0B] = self.cf;
        b[0x0C] = self.df;
        b[0x0D] = self.e4;
        for (0..4) |i| {
            b[0x0E + i] = self.name[3 - i]; // each half of the name is stored backwards
            b[0x12 + i] = self.name[7 - i];
        }
        b[0x16] = self.message_speed;
        b[0x17] = self.hp;
        b[0x18] = self.mp;
        b[0x19] = self.start_flag;
        @memset(b[0x1A..0x1E], 0xC8);
        std.mem.writeInt(u16, b[0x1E..0x20], crc(b[0..0x1E]), .little);
        return b;
    }

    /// $FB4A then $FB6B. Null if the CRC doesn't match. Bytes 0x1A-0x1D aren't checked.
    pub fn decode(b: *const [32]u8) ?SaveRecord {
        if (std.mem.readInt(u16, b[0x1E..0x20], .little) != crc(b[0..0x1E])) return null;
        var name: [8]u8 = undefined;
        for (0..4) |i| {
            name[3 - i] = b[0x0E + i];
            name[7 - i] = b[0x12 + i];
        }
        return .{
            .xp = std.mem.readInt(u16, b[0x00..0x02], .little),
            .gold = std.mem.readInt(u16, b[0x02..0x04], .little),
            .slots = b[0x04..0x08].*,
            .keys = b[0x08],
            .herbs = b[0x09],
            .equipment = b[0x0A],
            .cf = b[0x0B],
            .df = b[0x0C],
            .e4 = b[0x0D],
            .name = name,
            .message_speed = b[0x16],
            .hp = b[0x17],
            .mp = b[0x18],
            .start_flag = b[0x19],
        };
    }
};

/// $FBEF/$FC2A: CRC-16, polynomial 0x1021, MSB first, seeded 0x1D1D, over
/// bytes 0x1D down to 0x00. It's computed in $94/$95, the RNG state, so every
/// save and every load check leaves the RNG equal to the record's CRC.
pub fn crc(bytes: *const [0x1E]u8) u16 {
    var c: u16 = 0x1D1D;
    var i: usize = 0x1E;
    while (i > 0) {
        i -= 1;
        var byte = bytes[i];
        for (0..8) |_| {
            const top = ((c >> 8) ^ byte) & 0x80;
            c <<= 1;
            byte <<= 1;
            if (top != 0) c ^= 0x1021;
        }
    }
    return c;
}

/// SRAM ($6000-$7FFF) offsets.
pub const Sram = struct {
    pub const size = 0x2000;
    pub const slot_base = 0x0068; // $6068
    pub const slot_size = 0x140; // 10 copies of the record
    pub const copies = 10;
    pub const used_markers = 0x0035; // $6035-$6037: 0xC8 = used
    pub const used_bits = 0x0038; // $6038: bit n = slot n used
    pub const buffer = 0x0048; // $6048: the working copy of the record
    pub const bad_copies = 0x0432; // $6432-$6434: failed-copy counters per slot
    /// $6428 and $603B must both hold this, or the game wipes every slot ($F713).
    pub const signature = "KEN MASUTA";
    pub const signature_offsets = [2]u16{ 0x0428, 0x003B };

    pub fn slotOffset(slot: u2) usize {
        return slot_base + @as(usize, slot) * slot_size;
    }

    /// $F9DF: write all 10 copies and mark the slot used ($F7DA).
    pub fn save(sram: *[size]u8, slot: u2, rec: SaveRecord, rng: *Rng) void {
        const b = rec.encode();
        rng.state = std.mem.readInt(u16, b[0x1E..0x20], .little);
        const base = slotOffset(slot);
        sram[buffer..][0..0x20].* = b;
        for (0..copies) |i| sram[base + 0x20 * i ..][0..0x20].* = b;
        sram[used_markers + @as(usize, slot)] = 0xC8;
        sram[used_bits] = (sram[used_bits] | (@as(u8, 1) << slot)) & 0x07;
    }

    /// $FAC1: the first copy whose CRC matches, after which all 10 copies are
    /// rewritten from it. Null if none match; the boot check then erases the slot.
    pub fn load(sram: *[size]u8, slot: u2, rng: *Rng) ?SaveRecord {
        const base = slotOffset(slot);
        for (0..copies) |i| {
            const copy = sram[base + 0x20 * i ..][0..0x20];
            const computed = crc(copy[0..0x1E]);
            rng.state = computed;
            const stored = std.mem.readInt(u16, copy[0x1E..0x20], .little);
            // $FBE0 writes the computed CRC back into the copy before comparing.
            std.mem.writeInt(u16, copy[0x1E..0x20], computed, .little);
            if (stored != computed) {
                sram[bad_copies + @as(usize, slot)] +%= 1; // $FAF6
                continue;
            }
            const rec = SaveRecord.decode(copy).?;
            const good = copy.*;
            sram[buffer..][0..0x20].* = good;
            for (0..copies) |j| sram[base + 0x20 * j ..][0..0x20].* = good;
            return rec;
        }
        return null;
    }
};

test "save, corrupt a copy, load" {
    var sram: [Sram.size]u8 = @splat(0);
    var rng: Rng = .init(0);
    const rec: SaveRecord = .{
        .xp = 1300,
        .gold = 512,
        .slots = .{ 0x31, 0, 0, 0 },
        .keys = 9,
        .herbs = 2,
        .equipment = 0x6A,
        .cf = 0x10,
        .df = 0x08,
        .e4 = 0,
        .name = "Erdrick ".*,
        .message_speed = 1,
        .hp = 40,
        .mp = 20,
        .start_flag = 0xAB,
    };
    Sram.save(&sram, 1, rec, &rng);
    const saved_rng = rng.state;
    sram[Sram.slotOffset(1) + 3] ^= 0xFF; // break copy 0
    var loaded = Sram.load(&sram, 1, &rng).?;
    try std.testing.expectEqual(6, loaded.keys); // capped when saved
    loaded.keys = rec.keys;
    try std.testing.expectEqualDeep(rec, loaded);
    try std.testing.expectEqual(saved_rng, rng.state);
    try std.testing.expectEqual(0x02, sram[Sram.used_bits]);
}

pub const DragonlordOffer = enum { battle, bad_ending };

/// $E99E / $E9B1: both of the Dragonlord's forms skip the XP and gold
/// ($EA0A), so a win over either makes no gold roll.
pub fn givesRewards(id: EnemyId) bool {
    return id != .dragonlord1 and id != .dragonlord2;
}

pub const AfterDragonlord = union(enum) {
    /// $E9AC: the battle with his true form (0x27) starts ($E4DF).
    true_form,
    /// $E9EA: you're put here, at Charlock's gate.
    victory: Warp,
};

/// $E99E-$EA07, when a form of the Dragonlord falls; null for anyone else.
/// The true form: $E0 = 0 (so the 0x27 tile quirk ends), $E4 bit 2, HP and
/// MP to max, then out through warp entry 6 ($D9E2). No RNG calls.
pub fn dragonlordDefeated(id: EnemyId, e0: *u8, e4: *u8, hp: *u8, mp: *u8, max_hp: u8, max_mp: u8) ?AfterDragonlord {
    switch (id) {
        .dragonlord1 => return .true_form,
        .dragonlord2 => {
            e0.* = 0;
            e4.* |= Story.dragonlord_beaten;
            hp.* = max_hp;
            mp.* = max_mp;
            return .{ .victory = warps[6].from };
        },
        else => return null,
    }
}

/// $D4AB: he asks twice. Yes to both is the bad ending; any no starts the
/// battle with enemy 0x26.
pub fn dragonlordOffer(first_yes: bool, second_yes: bool) DragonlordOffer {
    return if (first_yes and second_yes) .bad_ending else .battle;
}

/// $D4E7: the bad ending clears these in RAM, prints the ending text and
/// hangs forever ($D530). Nothing is written to SRAM, so after a reset the
/// last save is still there.
pub fn badEnding(xp: *u16, gold: *u16, inv: *Inventory, equip: *u8, cf: *u8, df: *u8, e4: *u8) void {
    xp.* = 0;
    gold.* = 0;
    inv.* = .{};
    equip.* = 0;
    cf.* = 0;
    df.* = 0;
    e4.* = 0;
}

/// $D54C: with a full inventory, the king takes the first of these you have
/// and gives Gwaelin's Love in its place. The Cursed Belt can go even while
/// worn, and its curse bit stays set.
pub const love_swap = [7]Item{ .torch, .dragons_scale, .fighters_ring, .fairy_water, .wings, .cursed_belt, .staff_of_rain };

pub const Returned = struct { love: bool, taken: ?Item };

/// $D3B2: the king, while you carry the princess ($DF bit 0). No other code
/// path changes what you can do while carrying her.
pub fn returnPrincess(inv: *Inventory, df: *u8) Returned {
    var result: Returned = .{ .love = true, .taken = null };
    if (!inv.add(.gwaelins_love)) {
        result.love = false;
        for (love_swap) |item| {
            if (!inv.has(item)) continue;
            inv.remove(item);
            _ = inv.add(.gwaelins_love);
            result = .{ .love = true, .taken = item };
            break;
        }
    }
    df.* = (df.* & 0xFC) | Quest.princess_returned; // $D3F9
    return result;
}

test "the king makes room for Gwaelin's Love" {
    var inv: Inventory = .{ .slots = .{ 0xAC, 0xED, 0x79, 0xBC } }; // full, with the belt (9)
    var df: u8 = Quest.carrying_princess;
    const r = returnPrincess(&inv, &df);
    try std.testing.expectEqual(Item.cursed_belt, r.taken.?);
    try std.testing.expect(inv.has(.gwaelins_love));
    try std.testing.expectEqual(Quest.princess_returned, df);
}

/// PRG bank 0 ($8000-$BFFF), where the map tiles live. The tile data isn't
/// copied here; load it from the ROM (`rom[16..][0..0x4000]` of the .nes file)
/// and decode it once with Maps.fromBank0.
pub const Bank0 = *const [0x4000]u8;

fn read0(bank0: Bank0, addr: u16) u8 {
    return bank0[addr - 0x8000];
}

/// One row of bank 0 $801A (5 bytes per map number), copied to $11-$15 on loading a map.
pub const MapHeader = struct {
    /// $11/$12: packed tiles, or on the overworld the row-pointer table.
    data: u16,
    max_x: u8, // $13
    max_y: u8, // $14
    /// $15: what lies past the edge (the overworld computes shore water instead).
    border: Tile,
};

