/// $99E3: overworld nibble -> tile. Nibble 4 (water) never reads it: see shoreTile.
pub const overworld_tiles = [16]u8{ 0x00, 0x01, 0x02, 0x12, 0x0F, 0x10, 0x0B, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x05, 0x0F, 0x18, 0x19 };

/// $99F0, indexed by nibble + $16 (MapKind): 0x00-0x0F water by which sides
/// have land, 0x10-0x1F towns, 0x20-0x27 dungeons.
pub const map_tiles = [0x28]u8{
    0x0F, 0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26,
    0x00, 0x01, 0x0F, 0x0C, 0x10, 0x03, 0x04, 0x05, 0x0B, 0x06, 0x0D, 0x11, 0x13, 0x14, 0x0A, 0x0E,
    0x10, 0x03, 0x04, 0x05, 0x0C, 0x11, 0x17, 0x16,
};

/// Shore bits for map_tiles[0..16]: which neighbours are land.
pub const Shore = struct {
    pub const up: u8 = 1;
    pub const left: u8 = 2;
    pub const right: u8 = 4;
    pub const down: u8 = 8;
};

/// What the lookup reads besides the map.
pub const MapState = struct {
    map: u8, // $45
    /// $E0: the last tile stepped on, or the enemy ID after a battle.
    e0: u8 = 0,
    cf: u8 = 0, // Worn.rainbow_bridge, charlock_stairs_found
    df: u8 = 0, // Quest.carrying_princess / princess_returned
    chests: ChestLog = .{},
    doors: DoorLog = .{},
};

/// Bank 0's maps and NPC tables, decoded once. romcheck decodes them from the
/// ROM with fromBank0; the game gets the same struct at build time
/// (tools/romextract writes fromBank0's result out as Zig source).
pub const Maps = struct {
    /// Map m's nibble at (x, y) is nibbles[offsets[m] + y * (max_x + 1) + x].
    /// Overworld rows are run-length decoded ($AC5A); the other maps are
    /// unpacked two to a byte and masked as $ACE6 does.
    nibbles: [size]u8,
    /// Bank 0 $9734 (moving) and $974C (stationary), for maps 4-0x0E.
    npcs: [11][2]NpcRecords,

    pub const NpcRecords = struct {
        len: u8 = 0,
        /// As stored: x | type << 5, y | facing << 5, dialogue.
        rec: [10][3]u8 = @splat(.{ 0, 0, 0 }),
    };

    pub const offsets: [0x1F]usize = blk: {
        var o: [0x1F]usize = undefined;
        o[0] = 0;
        for (map_headers, 0..) |h, m| o[m + 1] = o[m] + (@as(usize, h.max_x) + 1) * (@as(usize, h.max_y) + 1);
        break :blk o;
    };
    pub const size = offsets[0x1E];

    pub fn nibble(self: *const Maps, map: u8, x: u8, y: u8) u8 {
        return self.nibbles[offsets[map] + @as(usize, y) * (@as(usize, map_headers[map].max_x) + 1) + x];
    }

    pub fn fromBank0(bank0: Bank0) Maps {
        var m: Maps = .{ .nibbles = @splat(0), .npcs = @splat(@splat(.{})) };
        for (map_headers[1..], 1..) |h, map| {
            for (0..@as(usize, h.max_y) + 1) |y| for (0..@as(usize, h.max_x) + 1) |x| {
                m.nibbles[offsets[map] + y * (@as(usize, h.max_x) + 1) + x] = romNibble(bank0, @intCast(map), @intCast(x), @intCast(y));
            };
        }
        for (&m.npcs, 0..) |*tables, i| for (tables, [2]u16{ 0x9734, 0x974C }) |*r, table| {
            const at = table + @as(u16, @intCast(i)) * 2;
            var p = @as(u16, read0(bank0, at)) | (@as(u16, read0(bank0, at + 1)) << 8);
            while (read0(bank0, p) != 0xFF and r.len < 10) : (p += 3) {
                r.rec[r.len] = .{ read0(bank0, p), read0(bank0, p + 1), read0(bank0, p + 2) };
                r.len += 1;
            }
        };
        return m;
    }
};

/// The overworld nibble at (x, y), straight from the RLE row ($AC5A, $ABF4).
fn overworldNibble(bank0: Bank0, x: u8, y: u8) u8 {
    const row = map_headers[1].data + @as(u16, y) * 2;
    var p = @as(u16, read0(bank0, row)) | (@as(u16, read0(bank0, row + 1)) << 8);
    var end: u8 = 0; // $3D: one past the run's last x (wraps like the 6502)
    while (true) : (p += 1) {
        end +%= (read0(bank0, p) & 0x0F) + 1;
        if (x < end) return read0(bank0, p) >> 4;
    }
}

/// $AC17's read of the map nibble at (x, y), inside the map.
fn romNibble(bank0: Bank0, map: u8, x: u8, y: u8) u8 {
    if (map == 0x01) return overworldNibble(bank0, x, y);
    const h = map_headers[map];
    const row_bytes: u16 = (h.max_x >> 1) + (h.max_x & 1);
    const byte = read0(bank0, h.data + @as(u16, y) * row_bytes + (x >> 1));
    return (if (x & 1 == 0) byte >> 4 else byte) & @as(u8, if (map >= 0x0C) 0x07 else 0x0F);
}

/// $ABF4: water and bridges don't count as land when picking shore tiles.
fn isLand(maps: *const Maps, x: u8, y: u8) bool {
    const n = maps.nibble(0x01, x, y);
    return n != 0x4 and n != 0xB;
}

/// $AB24: overworld water picks one of 16 tiles by which neighbours are land.
/// The rainbow bridge override isn't applied to the neighbours.
fn shoreTile(maps: *const Maps, x: u8, y: u8) Tile {
    var bits: u8 = 0;
    if (x != 0x77 and isLand(maps, x + 1, y)) bits += Shore.right;
    if (x != 0x00 and isLand(maps, x - 1, y)) bits += Shore.left;
    if (y != 0x00 and isLand(maps, x, y - 1)) bits += Shore.up;
    if (y != 0x77 and isLand(maps, x, y + 1)) bits += Shore.down;
    return @fromBackingInt(map_tiles[bits]);
}

/// $AB77: past the edge. On the overworld, one step outside picks shore water
/// from the single neighbour inside; anything further out is the border.
fn outsideTile(maps: *const Maps, map: u8, x: u8, y: u8) Tile {
    if (map == 0x01) {
        var bits: u8 = 0;
        if (y < 0x78 and (x == 0xFF or x == 0x78)) {
            if (x == 0xFF) {
                if (isLand(maps, 0x00, y)) bits = Shore.right;
            } else if (isLand(maps, 0x77, y)) bits = Shore.left;
            return @fromBackingInt(map_tiles[bits]);
        }
        if (x < 0x78 and (y == 0xFF or y == 0x78)) {
            if (y == 0xFF) {
                if (isLand(maps, x, 0x00)) bits = Shore.down;
            } else if (isLand(maps, x, 0x77)) bits = Shore.up;
            return @fromBackingInt(map_tiles[bits]);
        }
    }
    return map_headers[map].border;
}

/// Bank 0 $AC17: the tile at (x, y) on the current map. Coordinates are
/// unsigned, so one step left of x = 0 is x = 0xFF.
pub fn tileAt(maps: *const Maps, s: MapState, x: u8, y: u8) Tile {
    const h = map_headers[s.map];
    if (x > h.max_x) return outsideTile(maps, s.map, x, y);
    if (s.e0 == 0x27) return .blank; // after the Dragonlord's second form, before y is checked
    if (y > h.max_y) return outsideTile(maps, s.map, x, y);

    if (s.map == 0x01) {
        if (x == 0x40 and y == 0x31 and s.cf & Worn.rainbow_bridge != 0) return .bridge;
        const n = maps.nibble(0x01, x, y);
        if (n == 0x4) return shoreTile(maps, x, y);
        return @fromBackingInt(overworld_tiles[n]);
    }

    const nibble = maps.nibble(s.map, x, y);
    const tile: Tile = @fromBackingInt(map_tiles[nibble + @backingInt(mapKind(s.map))]);
    return switch (tile) {
        .princess => if (s.df & (Quest.carrying_princess | Quest.princess_returned) != 0) .brick else tile,
        // Charlock's stairs behind the throne look like barrier until found.
        .stairs_down => if (s.map == 0x02 and x == 0x0A and y == 0x01 and s.cf & charlock_stairs_found == 0) .barrier else tile,
        .chest => if (s.chests.opened(x, y)) .brick else tile,
        .door => if (s.doors.opened(x, y)) .brick else tile,
        else => tile,
    };
}

/// Any of the 16 water tiles.
pub fn isWater(t: Tile) bool {
    const v = @backingInt(t);
    return v == 0x0F or (v >= 0x18 and v <= 0x26);
}

test "past the edge" {
    const empty: Maps = .{ .nibbles = @splat(0), .npcs = @splat(@splat(.{})) };
    // A town's border, and far off the overworld (no row is read).
    try std.testing.expectEqual(Tile.grass, tileAt(&empty, .{ .map = 0x04 }, 30, 5));
    try std.testing.expectEqual(Tile.empty, tileAt(&empty, .{ .map = 0x05 }, 3, 0xFF));
    try std.testing.expectEqual(Tile.water, tileAt(&empty, .{ .map = 0x01 }, 0xFF, 0xFF));
}

/// Bank 0 $B1CC: a move goes ahead when the target tile is below 0x0E.
/// Town NPCs ($51-$8C) block too; that check isn't ported here.
pub fn walkable(t: Tile) bool {
    return @backingInt(t) < 0x0E;
}

