    .{ .from = .{ .map = 0x14, .x = 9, .y = 0 }, .to = .{ .map = 0x14, .x = 0, .y = 0 } },
    .{ .from = .{ .map = 0x14, .x = 9, .y = 6 }, .to = .{ .map = 0x06, .x = 10, .y = 29 } },
    .{ .from = .{ .map = 0x16, .x = 0, .y = 0 }, .to = .{ .map = 0x17, .x = 0, .y = 0 } },
    .{ .from = .{ .map = 0x16, .x = 6, .y = 5 }, .to = .{ .map = 0x17, .x = 6, .y = 5 } },
    .{ .from = .{ .map = 0x16, .x = 12, .y = 12 }, .to = .{ .map = 0x17, .x = 12, .y = 12 } },
    .{ .from = .{ .map = 0x18, .x = 1, .y = 18 }, .to = .{ .map = 0x19, .x = 11, .y = 2 } },
    .{ .from = .{ .map = 0x19, .x = 1, .y = 1 }, .to = .{ .map = 0x1A, .x = 14, .y = 1 } },
    .{ .from = .{ .map = 0x19, .x = 12, .y = 1 }, .to = .{ .map = 0x1A, .x = 18, .y = 1 } },
    .{ .from = .{ .map = 0x19, .x = 5, .y = 6 }, .to = .{ .map = 0x1A, .x = 6, .y = 11 } },
    .{ .from = .{ .map = 0x19, .x = 1, .y = 10 }, .to = .{ .map = 0x1A, .x = 2, .y = 17 } },
    .{ .from = .{ .map = 0x19, .x = 12, .y = 10 }, .to = .{ .map = 0x1A, .x = 18, .y = 13 } },
    .{ .from = .{ .map = 0x1A, .x = 9, .y = 5 }, .to = .{ .map = 0x1B, .x = 0, .y = 4 } },
    .{ .from = .{ .map = 0x1A, .x = 10, .y = 9 }, .to = .{ .map = 0x1B, .x = 5, .y = 4 } },
    .{ .from = .{ .map = 0x1C, .x = 9, .y = 9 }, .to = .{ .map = 0x1D, .x = 8, .y = 9 } },
};

/// $D941: an entrance tile, or STAIRS on stairs down. The first entry whose
/// `from` is here; null prints a message and nothing happens.
pub fn warpForward(at: Warp) ?Warp {
    for (warps) |w| if (std.meta.eql(w.from, at)) return w.to;
    return null;
}

/// $D9C3: STAIRS on stairs up. The first entry whose `to` is here.
pub fn warpBack(at: Warp) ?Warp {
    for (warps) |w| if (std.meta.eql(w.to, at)) return w.from;
    return null;
}

/// Bank 0 $B219/$B228: walking off the edge of any map but the overworld
/// leaves by the first entry whose `to` is on this map. Only the first 49
/// entries are searched (CPX #$93), so Erdrick's Cave B2 (0x1D) has no edge exit;
/// walls surround it anyway.
pub fn edgeExit(map: u8) ?Warp {
    for (warps[0..49]) |w| if (w.to.map == map) return w.from;
    return null;
}

/// $D9AF: the STAIRS command.
pub fn stairs(maps: *const Maps, s: MapState, x: u8, y: u8) ?Warp {
    const at: Warp = .{ .map = s.map, .x = x, .y = y };
    return switch (tileAt(maps, s, x, y)) {
        .stairs_down => warpForward(at),
        .stairs_up => warpBack(at),
        else => null, // "There are no stairs here."
    };
}

/// Where a move lands, as the ROM resolves it: bounds ($B219), then the step ($CBF7).
pub const Move = union(enum) {
    blocked,
    /// Off the edge of a town, castle or dungeon.
    exit: Warp,
    /// Moved; run takeStep with this tile (an entrance tile ends in warpForward).
    step: Tile,
};

pub fn move(maps: *const Maps, s: MapState, x: u8, y: u8) Move {
    const t = tileAt(maps, s, x, y);
    if (!walkable(t)) return .blocked;
    const h = map_headers[s.map];
    // With no entry, $B228 just returns with you outside the map. It can't
    // happen: the maps without one (5, 0x1D) and the overworld have unwalkable borders.
    if (x > h.max_x or y > h.max_y) return if (edgeExit(s.map)) |w| .{ .exit = w } else .blocked;
    return .{ .step = t };
}

test "Tantegel: in, up to the king, and back out" {
    const castle = warpForward(.{ .map = 0x01, .x = 43, .y = 43 }).?;
    try std.testing.expectEqual(Warp{ .map = 0x04, .x = 11, .y = 29 }, castle);
    try std.testing.expectEqual(Warp{ .map = 0x05, .x = 8, .y = 8 }, warpBack(.{ .map = 0x04, .x = 7, .y = 7 }).?);
    try std.testing.expectEqual(Warp{ .map = 0x01, .x = 43, .y = 43 }, edgeExit(0x04).?);
    // No entry leads into the throne room, so it has no edge exit; its border (0x15) isn't walkable.
    try std.testing.expectEqual(null, edgeExit(0x05));
    try std.testing.expect(!walkable(map_headers[0x05].border));
}
